// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account, uint256 tokenId) public {
        vm.assume(tx.origin != address(0));
        vm.assume(account != address(0));

        uint256 balance = c.balanceOf(account, tokenId);
        uint256 maxSupply = type(uint256).max; // no easily accessible total supply, but we know balanceOf is bounded

        assertTrue(balance <= type(uint256).max);
    }
}

